/**
 * Model catalog (M4, #76): price, tool and vision data for the live model list.
 *
 * Source is the open models.dev database that OpenCode also uses. The relay
 * fetches it server-side, keeps it in memory for six hours and, when models.dev
 * cannot be reached or sends data we cannot read, falls back to a small bundled
 * snapshot (`model-snapshot.js`, regenerated by `npm run models:snapshot`).
 * Only the OpenAI, Anthropic and OpenCode entries are kept. No credential is
 * ever sent to models.dev.
 */
import { createCatalogGet, CATALOG_URL } from './providers.js';
import { MODEL_SNAPSHOT } from './model-snapshot.js';
import { MODEL_ID_PATTERN, record } from './validation.js';

/** Noddy provider → models.dev provider ID. OpenCode Zen is `opencode` there. */
export const CATALOG_PROVIDERS = Object.freeze({
	openai: 'openai',
	anthropic: 'anthropic',
	'opencode-zen': 'opencode',
});

export const CATALOG_TTL_MS = 6 * 60 * 60 * 1000;
// After a failed fetch, serve the fallback for a minute instead of retrying on every request.
export const CATALOG_RETRY_MS = 60 * 1000;
export const CATALOG_TIMEOUT_MS = 8000;
// The live file is about 6 MB because it covers 200+ providers.
export const CATALOG_MAX_BYTES = 24 * 1024 * 1024;
const MAX_MODELS_PER_PROVIDER = 2000;

/**
 * @typedef {Object} CatalogEntry
 * @property {boolean|null} tools   tool calling; null when the catalog does not say
 * @property {boolean|null} vision  accepts image input; null when unknown
 * @property {{input:number, output:number}|null} price  USD per million tokens; null when unknown
 * @property {string|null} released  release date as the catalog writes it
 */

const isPrice = (value) =>
	typeof value === 'number' && Number.isFinite(value) && value >= 0 && value <= 100000;

/**
 * One models.dev model → the few fields Noddy uses. Anything unreadable becomes
 * null (unknown), never a guess.
 * @param {unknown} raw
 * @returns {CatalogEntry|null}
 */
export function normalizeEntry(raw) {
	if (!record(raw)) return null;
	// models.dev marks embedding, image and realtime models with a `type`; none is a chat model
	// the agent can drive, whatever its tool_call flag says.
	const notChat = typeof raw.type === 'string' && raw.type.length > 0;
	const tools = notChat ? false : typeof raw.tool_call === 'boolean' ? raw.tool_call : null;
	const input =
		record(raw.modalities) && Array.isArray(raw.modalities.input) ? raw.modalities.input : null;
	const cost = record(raw.cost) ? raw.cost : null;
	return {
		tools,
		vision: input ? input.includes('image') : null,
		price:
			cost && isPrice(cost.input) && isPrice(cost.output)
				? { input: cost.input, output: cost.output }
				: null,
		released:
			typeof raw.release_date === 'string' && /^\d{4}(-\d{2}){0,2}$/.test(raw.release_date)
				? raw.release_date
				: null,
	};
}

/**
 * The whole models.dev document → `{provider: Map<modelId, CatalogEntry>}` for
 * the three tracked providers. Throws when any of them is missing or empty, so a
 * changed or broken document is never mistaken for "these models have no data".
 * @param {unknown} raw
 * @returns {Record<string, Map<string, CatalogEntry>>}
 */
export function normalizeCatalog(raw) {
	if (!record(raw)) throw new Error('Malformed model catalog');
	/** @type {Record<string, Map<string, CatalogEntry>>} */
	const catalog = {};
	for (const [provider, catalogId] of Object.entries(CATALOG_PROVIDERS)) {
		const models =
			record(raw[catalogId]) && record(raw[catalogId].models) ? raw[catalogId].models : null;
		if (!models) throw new Error('Malformed model catalog');
		const map = new Map();
		for (const [id, value] of Object.entries(models)) {
			if (map.size >= MAX_MODELS_PER_PROVIDER) break;
			if (!MODEL_ID_PATTERN.test(id)) continue;
			const entry = normalizeEntry(value);
			if (entry) map.set(id, entry);
		}
		if (!map.size) throw new Error('Malformed model catalog');
		catalog[provider] = map;
	}
	return catalog;
}

/** Plain, JSON-ready form of a normalized catalog (what the snapshot file stores). */
export function catalogToPlain(catalog) {
	return Object.fromEntries(
		Object.entries(catalog).map(([provider, map]) => [provider, Object.fromEntries(map)])
	);
}

/**
 * The bundled snapshot → the same shape `normalizeCatalog` returns.
 * @param {{providers: Record<string, Record<string, CatalogEntry>>}} snapshot
 */
export function catalogFromSnapshot(snapshot) {
	return Object.fromEntries(
		Object.keys(CATALOG_PROVIDERS).map((provider) => [
			provider,
			new Map(Object.entries(snapshot.providers[provider] ?? {})),
		])
	);
}

/**
 * Catalog entry for a live model ID. Providers also serve dated snapshots
 * (`claude-haiku-4-5-20251001`) and `-latest` aliases that the catalog may list
 * only under the plain name; they share its capabilities.
 * @param {Map<string, CatalogEntry>} models
 * @param {string} id
 * @returns {CatalogEntry|undefined}
 */
export function lookupEntry(models, id) {
	if (models.has(id)) return models.get(id);
	const plain = id.replace(/-(\d{8}|\d{4}-\d{2}-\d{2}|latest)$/, '');
	return plain !== id ? models.get(plain) : undefined;
}

// IDs of models that are plainly not chat models, used only when the catalog has no entry for
// the ID. They cannot call tools, so they are shown as unusable rather than "unknown".
const NOT_CHAT_ID =
	/(^|[-_.:/])(embed|embedding|embeddings|whisper|tts|dall-e|moderation|transcribe|realtime|davinci|babbage|rerank|sora|image)(?=$|[-_.:/\d])/i;

/** @param {string} id */
export const isClearlyNotChat = (id) => NOT_CHAT_ID.test(id);

/**
 * Read a JSON response with a hard size limit, so a hostile or broken upstream
 * cannot make the relay buffer an unbounded body.
 * @param {Response} response
 * @param {number} maxBytes
 */
export async function readJsonCapped(response, maxBytes) {
	if (Number(response.headers?.get('content-length')) > maxBytes) {
		await response.body?.cancel?.().catch(() => {});
		throw new Error('Response too large');
	}
	if (!response.body?.getReader) {
		const text = await response.text();
		if (text.length > maxBytes) throw new Error('Response too large');
		return JSON.parse(text);
	}
	const reader = response.body.getReader();
	const chunks = [];
	let size = 0;
	for (;;) {
		const { done, value } = await reader.read();
		if (done) break;
		size += value.byteLength;
		if (size > maxBytes) {
			await reader.cancel().catch(() => {});
			throw new Error('Response too large');
		}
		chunks.push(value);
	}
	return JSON.parse(Buffer.concat(chunks).toString('utf8'));
}

/**
 * The start of a response body as text, never more than `maxBytes` and never throwing.
 * Used to find a failed provider's message; the text itself is not relayed (errors.js).
 * @param {Response} response
 * @param {number} maxBytes
 * @returns {Promise<string>}
 */
export async function readTextCapped(response, maxBytes) {
	try {
		if (!response.body?.getReader) return (await response.text()).slice(0, maxBytes);
		const reader = response.body.getReader();
		const chunks = [];
		let size = 0;
		while (size < maxBytes) {
			const { done, value } = await reader.read();
			if (done) break;
			chunks.push(value);
			size += value.byteLength;
		}
		await reader.cancel().catch(() => {});
		return Buffer.concat(chunks).subarray(0, maxBytes).toString('utf8');
	} catch {
		return '';
	}
}

/**
 * Fetch and read the live catalog once.
 * @param {ReturnType<typeof createCatalogGet>} get
 * @param {{signal?: AbortSignal, maxBytes?: number}} options
 */
export async function fetchCatalog(get, { signal, maxBytes = CATALOG_MAX_BYTES } = {}) {
	const response = await get(CATALOG_URL, { signal });
	if (!response.ok) {
		await response.body?.cancel?.().catch(() => {});
		throw new Error('Model catalog unavailable');
	}
	return normalizeCatalog(await readJsonCapped(response, maxBytes));
}

/**
 * In-memory catalog with a time-to-live. `get()` never rejects: it returns the
 * live catalog, the cached one (also when stale and models.dev is down), or the
 * bundled snapshot, with `source` saying which.
 * @param {Object} [options]
 * @param {typeof fetch} [options.transport]
 * @param {() => number} [options.now]
 * @param {number} [options.ttlMs]
 * @param {number} [options.retryMs]
 * @param {number} [options.timeoutMs]
 * @param {number} [options.maxBytes]
 * @param {typeof MODEL_SNAPSHOT} [options.snapshot]
 * @returns {{get: () => Promise<{catalog: Record<string, Map<string, CatalogEntry>>, source: 'live'|'cache'|'snapshot'}>}}
 */
export function createCatalogSource({
	transport,
	now = Date.now,
	ttlMs = CATALOG_TTL_MS,
	retryMs = CATALOG_RETRY_MS,
	timeoutMs = CATALOG_TIMEOUT_MS,
	maxBytes = CATALOG_MAX_BYTES,
	snapshot = MODEL_SNAPSHOT,
} = {}) {
	const get = createCatalogGet(transport);
	let cached = null;
	let failedAt = null;
	let pending = null;
	let bundled = null;

	const fallback = () =>
		cached
			? { catalog: cached.catalog, source: /** @type {const} */ ('cache') }
			: {
					catalog: (bundled ??= catalogFromSnapshot(snapshot)),
					source: /** @type {const} */ ('snapshot'),
			  };

	async function refresh() {
		try {
			const catalog = await fetchCatalog(get, {
				signal: AbortSignal.timeout(timeoutMs),
				maxBytes,
			});
			cached = { catalog, at: now() };
			failedAt = null;
			return { catalog, source: /** @type {const} */ ('live') };
		} catch {
			failedAt = now();
			return fallback();
		}
	}

	return {
		get() {
			const time = now();
			if (cached && time - cached.at < ttlMs) {
				return Promise.resolve({ catalog: cached.catalog, source: /** @type {const} */ ('cache') });
			}
			if (failedAt !== null && time - failedAt < retryMs) return Promise.resolve(fallback());
			// Concurrent requests share one fetch.
			pending ??= refresh().finally(() => {
				pending = null;
			});
			return pending;
		},
	};
}
